'use strict';
const $=s=>document.querySelector(s);
const norm=s=>String(s??'').normalize('NFKC').toLowerCase().replace(/\s+/g,'').replace(/頓/g,'屯');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,mode='items',limit=25,query='',category='';
const labels={items:'項目・略号',cases:'算定パターン',rules:'留意事項・全項目',pages:'公式資料の全文検索'};
const helps={items:'添付表の全行を掲載。同じ略号も算定する本体が違う場合は別項目として表示します。',cases:'条文から整理した具体例です。「対象」は、記載した条件に加え、その項目の共通要件を満たす場合です。全事例の網羅は未完了です。',rules:'調剤の留意事項を項目ごとに収録。例外・回数制限・記録要件を省略せず確認できます。',pages:'点数表・留意事項・疑義解釈その1〜12などをページ単位で検索。文が次ページに続く場合と表組みは原PDFで確認してください。'};
function link(url,text='厚生労働省の原文を開く'){return `<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener">${esc(text)}</a>`;}
function bodyText(t,source){return window.SourceText.render(t,source);}
function tokens(){return query.normalize('NFKC').trim().split(/\s+/).filter(Boolean).map(norm);}
function relatedRules(x){return x.rules.map(id=>data.rules.find(r=>r.id===id)).filter(Boolean);}
function searchable(x,m){if(m==='items')return [x.abbr,x.code,x.name,x.division,x.description,x.points,...x.corrections,...relatedRules(x).map(r=>r.text)].join(' ');return [x.title,x.category,x.result,x.parent,x.text,x.kind].join(' ');}
function filtered(m){const terms=tokens();return data[m].filter(x=>(m!==mode||!category||(x.category||x.kind||'')===category)&&terms.every(t=>x._search.includes(t))).sort((a,b)=>{if(!terms.length)return 0;const score=x=>terms.reduce((s,t)=>s+(norm(x.abbr)===t?20:0)+(norm(x.name||x.title).includes(t)?5:0),0);return score(b)-score(a);});}
function snippet(x){const text=x.text||'';if(window.SourceText.isTable(text))return '表を含む資料です。「本文を省略せず読む」から、列見出し・項目名・注記を含む表全体を確認してください。';if(!query)return text.replace(/\s+/g,' ').slice(0,160)+'…';const compact=text.replace(/\s+/g,' ');const term=query.trim().split(/\s+/)[0];const i=compact.indexOf(term);return (i>30?'…':'')+compact.slice(Math.max(0,i-35),Math.max(0,i-35)+200)+'…';}
function renderItem(x){const rules=relatedRules(x);return `<article class="card" id="${x.id}"><div class="meta"><span class="badge abbr">${esc(x.abbr)}</span><span>${x.code?'制御コード '+esc(x.code):'元表の制御コードは空欄'}</span></div><h3>${esc(x.name)}</h3><div class="points">${esc(x.points)} <span class="hint">（元表ベース・補足を確認）</span></div>${x.corrections.map(t=>`<div class="notice">${esc(t)}</div>`).join('')}${x.division?`<p>${esc(x.division)}</p>`:''}<details><summary>元表の説明を見る</summary><p class="original">${esc(x.description)}</p><p class="hint">元表 ${x.originalRow}行。短い説明は要件の全てではありません。</p></details>${rules.map(r=>`<details><summary>${esc(r.title)} — 算定条件・留意事項</summary>${bodyText(r.text,r)}${link(r.url,'留意事項 PDF '+r.page+'ページ')}</details>`).join('')}<div class="related"><button data-find="${esc(searchName(x))}">この項目の点数表・施設基準・疑義解釈を検索</button></div></article>`;}
function searchName(x){let s=x.name.split('を算定')[0];const known=['調剤時残薬調整加算','薬学的有害事象等防止加算','特定薬剤管理指導加算','かかりつけ薬剤師フォローアップ加算','かかりつけ薬剤師訪問加算','麻薬管理指導加算','医療用麻薬持続注射療法加算','乳幼児服薬指導加算','小児特定加算','在宅中心静脈栄養法加算','吸入薬指導加算','在宅薬学総合体制加算','外来服薬支援料','服用薬剤調整支援料','服薬情報等提供料','服薬管理指導料','調剤管理料'];return known.find(k=>s.includes(k))||s.replace(/[1-9１２３イロハニ]+$/,'').split('：')[0];}
function renderOther(x){const title=x.title;return `<article class="card" id="${x.id}"><div class="meta"><span class="badge">${esc(x.category||x.kind||x.parent)}</span>${x.result?`<span class="result-type">${esc(x.result)}</span>`:''}${x.page?`<span>PDF ${x.page}ページ</span>`:''}</div><h3>${esc(title)}</h3>${mode==='cases'?`<p>${esc(x.text)}</p>`:`<p class="snippet">${esc(snippet(x))}</p><details><summary>本文を省略せず読む</summary>${bodyText(x.text,x)}</details>`}${link(x.url)}${mode==='pages'?`<p class="hint">${esc(data.documents.find(d=>d.id===x.doc)?.title)}</p>`:''}</article>`;}
function render(){if(!data)return;const rows=filtered(mode);$('#mode-title').textContent=labels[mode];$('#mode-help').textContent=helps[mode];$('#count').textContent=`${rows.length}件${query?' · 「'+query+'」':''}`;$('#results').innerHTML=rows.slice(0,limit).map(x=>mode==='items'?renderItem(x):renderOther(x)).join('')||`<div class="empty"><strong>該当する結果がありません</strong><p>語を短くするか、別の検索対象で調べてください。</p><div class="cross">${Object.keys(labels).filter(m=>m!==mode).map(m=>`<button data-mode="${m}">${labels[m]}（${filtered(m).length}件）</button>`).join('')}</div></div>`;$('#more').hidden=rows.length<=limit;$('#more').textContent=`さらに表示（残り${Math.max(0,rows.length-limit)}件）`;for(const m of Object.keys(labels)){$('#n-'+m).textContent=(query?filtered(m).length:data[m].length);const b=$(`#modes [data-mode="${m}"]`);b.classList.toggle('selected',m===mode);b.setAttribute('aria-pressed',String(m===mode));}const url=new URL(location.href);url.searchParams.set('view',mode);query?url.searchParams.set('q',query):url.searchParams.delete('q');history.replaceState(null,'',url);}
function changeMode(m){mode=m;category='';limit=25;const opts=[...new Set(data[m].map(x=>x.category||x.kind).filter(Boolean))];$('#category').innerHTML='<option value="">すべて</option>'+opts.map(v=>`<option>${esc(v)}</option>`).join('');$('#category').disabled=!opts.length;render();}
$('#search-form').addEventListener('submit',e=>{e.preventDefault();query=$('#query').value.trim();limit=25;render();});
let timer;$('#query').addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{query=$('#query').value.trim();limit=25;render();},180);});
$('#category').addEventListener('change',e=>{category=e.target.value;limit=25;render();});$('#more').addEventListener('click',()=>{limit+=25;render();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!data)return;if(b.dataset.mode)changeMode(b.dataset.mode);if(b.dataset.query){query=b.dataset.query;$('#query').value=query;limit=25;render();}if(b.dataset.find){query=b.dataset.find;$('#query').value=query;changeMode('pages');$('#query').focus();window.scrollTo({top:0,behavior:'auto'});}});
fetch('./data.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json();}).then(d=>{data=d;for(const m of Object.keys(labels))for(const x of data[m])x._search=norm(searchable(x,m));$('#coverage').textContent=data.coverage.note;$('#sources').innerHTML=data.documents.map(d=>link(d.url,d.title+`（収録${d.pages}ページ）`)).join('');const params=new URLSearchParams(location.search);query=params.get('q')||'';$('#query').value=query;changeMode(Object.hasOwn(labels,params.get('view'))?params.get('view'):'items');}).catch(e=>{$('#count').textContent='読み込めませんでした';$('#results').innerHTML='<div class="empty">データを読み込めませんでした。ページを再読み込みしてください。<p>'+link('https://www.mhlw.go.jp/stf/newpage_67729.html','厚生労働省の資料一覧を開く')+'</p></div>';console.error(e);});
